/**
 * A generated agent that does not load must not be reported as loaded.
 *
 * `morning_brief_agent.js` sat in a real `~/.openrappter/agents/` failing on
 * every single gateway start for at least ten days (#144):
 *
 *     WARN [agents] Agent file failed to load
 *       {"file":".../morning_brief_agent.js","reason":"Unexpected identifier 'as'"}
 *
 * Its header says `Auto-generated by LearnNewAgent`, and line 35 is `} as
 * const;` — TypeScript syntax in a file written with a `.js` extension and
 * imported as plain JavaScript. So the product generated a file it could not
 * load, and then said:
 *
 *     status:  'success'
 *     message: "Created and loaded agent 'morning_brief'"
 *
 * The failure was recorded, but only as `hot_loaded: false` and
 * `hot_load_error` further down the same payload, under a `status` that every
 * caller reads as success — `agentResultIsError` classifies on exactly that
 * field. The user is told the agent exists and works; the warning then prints
 * on every start, where nobody is reading.
 *
 * This file pins the honest reporting. It deliberately does not assert the
 * file is deleted: a broken file the user can open and fix is more useful than
 * a silent rollback, as long as the result says so.
 */
import { describe, expect, it, beforeEach, afterEach } from 'vitest';
import { mkdtemp, rm, readFile, readdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { LearnNewAgent } from '../LearnNewAgent.js';
import type { LLMProvider } from '../../providers/types.js';

let dir = '';
beforeEach(async () => { dir = await mkdtemp(join(tmpdir(), 'learnnew-load-')); });
afterEach(async () => { await rm(dir, { recursive: true, force: true }); });

/** A provider that answers with whatever the test wants, without a model. */
function fakeProvider(content: string): LLMProvider {
  return {
    name: 'fake',
    chat: async () => ({ content }) as never,
  } as unknown as LLMProvider;
}

const DESC = 'Compute the ISBN-13 check digit for a 12-digit prefix';

/** The exact shape that broke: a TypeScript `as const` in a .js file. */
const TYPESCRIPT_IN_JS = `/** Auto-generated by LearnNewAgent */
const CONFIG = { city: 'Smyrna' } as const;

export function createAgent(BasicAgent) {
  class IsbnAgent extends BasicAgent {
    constructor() {
      super('Isbn', { name: 'Isbn', description: 'x', parameters: { type: 'object', properties: {}, required: [] } });
    }
    async perform() { return JSON.stringify({ status: 'success', city: CONFIG.city }); }
  }
  return IsbnAgent;
}`;

/** The same agent without the TypeScript, so the fix cannot be "always error". */
const LOADABLE = TYPESCRIPT_IN_JS.replace(" as const", "");

describe('a generated agent that cannot load is reported as a failure', () => {
  it('does not claim success when the file does not import', async () => {
    const agent = new LearnNewAgent(dir);
    agent.setProvider(fakeProvider(TYPESCRIPT_IN_JS));
    const res = JSON.parse(await agent.execute({ action: 'create', description: DESC, name: 'Isbn' })) as Record<string, unknown>;

    // Sanity: the generated branch was reached, not the scaffold.
    expect(res.implementation).toBe('generated');

    // The field every caller classifies on. `agentResultIsError` reads exactly
    // this, so 'success' means every composition layer treats a broken agent
    // as a working one.
    expect(res.status).toBe('error');
    expect(res.hot_loaded).toBe(false);
    // Must not claim it loaded; saying it could NOT load is the point.
    expect(String(res.message)).not.toMatch(/Created and loaded/i);
    expect(String(res.message)).toMatch(/could not be loaded/i);
  });

  it('says why, and where the file is', async () => {
    const agent = new LearnNewAgent(dir);
    agent.setProvider(fakeProvider(TYPESCRIPT_IN_JS));
    const res = JSON.parse(await agent.execute({ action: 'create', description: DESC, name: 'Isbn' })) as Record<string, unknown>;

    // Without the reason the user has a broken file and no idea which line the
    // parser objected to.
    expect(String(res.hot_load_error).length).toBeGreaterThan(3);
    expect(String(res.file_path)).toContain(dir);
  });

  it('leaves the file on disk so it can be fixed', async () => {
    const agent = new LearnNewAgent(dir);
    agent.setProvider(fakeProvider(TYPESCRIPT_IN_JS));
    await agent.execute({ action: 'create', description: DESC, name: 'Isbn' });

    const written = (await readdir(dir)).filter((f) => f.endsWith('_agent.js'));
    expect(written.length).toBe(1);
    expect(await readFile(join(dir, written[0]), 'utf-8')).toContain('as const');
  });

  it('still reports success for a generated agent that does load', async () => {
    const agent = new LearnNewAgent(dir);
    agent.setProvider(fakeProvider(LOADABLE));
    const res = JSON.parse(await agent.execute({ action: 'create', description: DESC, name: 'Isbn' })) as Record<string, unknown>;

    expect(res.implementation).toBe('generated');
    expect(res.status).toBe('success');
    expect(res.hot_loaded).toBe(true);
  });
});
